assert.match(run.stdout, /FRONTMATTER_EXTRA_FIELDS/)
assert.match(run.stdout, /BROKEN_LOCAL_REFERENCE/)

fs.rmSync(root, { recursive: true, force: true })
console.log('openvela skill suite validator self-test passed')

