    info = payload.get("info")
    usage = None
    if isinstance(info, dict):
        usage = info.get("last_token_usage") or info.get("total_token_usage")
    if not isinstance(usage, dict):
        return None
    tokens_in = usage.get("input_tokens")
    tokens_out = usage.get("output_tokens")
    if not isinstance(tokens_in, int) or not isinstance(tokens_out, int):
        return None
    return tokens_in, tokens_out


def expand_codex_event(raw_event: dict, fallback_ts: str, state: dict | None = None) -> list[dict]:
    """Convert one Codex rollout line into zero-or-more contest events."""
    state = state if state is not None else {}
    out: list[dict] = []
    top_type = raw_event.get("type")
    payload = raw_event.get("payload")
    ts = raw_event.get("timestamp") or fallback_ts
    if not isinstance(payload, dict):
        payload = {}
    common: dict = {"ts": ts}

    if top_type in CODEX_CONTROL_TOP_TYPES:
        return out

    if top_type == "event_msg":
        usage = codex_token_usage(raw_event)
        if usage:
            # Codex reports usage per turn; carry it onto the next assistant
            # event so the field lands where the schema expects it.
            state["pending_tokens_in"] = usage[0]
            state["pending_tokens_out"] = usage[1]
            state["tokens_total"] = (
                (payload.get("info") or {}).get("total_token_usage") or {}
            ).get("total_tokens", state.get("tokens_total"))
        elif payload.get("type") in CODEX_SKIP_EVENT_MSG_TYPES:
            state["skipped_control"] = state.get("skipped_control", 0) + 1
        return out

    if top_type == "compacted":
        text = payload.get("message")
        if isinstance(text, str) and text:
            out.append({**common, "role": "system", "text": text,
                        "metadata": {"codex_compaction_summary": True}})
        return out

    if top_type != "response_item":
        return out

    item_type = payload.get("type")

    if item_type == "message":
        role = CODEX_ROLE_MAP.get(str(payload.get("role") or "").lower(), "system")
        content = payload.get("content")
        if isinstance(content, str):
            if content:
                out.append({**common, "role": role, "text": content})
            return out
        if not isinstance(content, list):
            return out
        for block in content:
            if not isinstance(block, dict):
                continue
            block_type = block.get("type")
            if block_type in CODEX_TEXT_BLOCK_TYPES:
                text = block.get("text")
                if text:
                    out.append({**common, "role": role, "text": text})
            elif block_type == "input_image":
                state["skipped_images"] = state.get("skipped_images", 0) + 1
            else:
                out.append({**common, "role": role,
                            "text": f"[unsupported codex content block: {block_type}]",
                            "metadata": {"dropped": True, "original_type": block_type}})
        return out

    if item_type == "reasoning":
        parts: list[str] = []
        summary = payload.get("summary")
        if isinstance(summary, list):
            for block in summary:
                if isinstance(block, dict):
                    text = block.get("text")
                    if isinstance(text, str) and text:
                        parts.append(text)
        content = payload.get("content")
        if isinstance(content, list):
            for block in content:
                if isinstance(block, dict):
                    text = block.get("text")
                    if isinstance(text, str) and text:
                        parts.append(text)
        if parts:
            out.append({**common, "role": "assistant", "thinking": "\n".join(parts)})
        else:
            # Codex stores reasoning encrypted; there is no exportable text.
            state["encrypted_reasoning"] = state.get("encrypted_reasoning", 0) + 1
        return out

    if item_type in CODEX_TOOL_CALL_TYPES:
        raw_input = payload.get("input")
        if raw_input is None:
            raw_input = payload.get("arguments")
        if isinstance(raw_input, str):
            try:
                raw_input = json.loads(raw_input)
            except (ValueError, TypeError):
                pass
        out.append({
            **common, "role": "tool",
            "tool_name": str(payload.get("name") or item_type),
            "tool_call_id": str(payload.get("call_id") or payload.get("id") or state.get("tool_seq", 0)),
            "input": raw_input, "output": None,
        })
        state["tool_seq"] = state.get("tool_seq", 0) + 1
        return out

    if item_type in CODEX_TOOL_OUTPUT_TYPES:
        out.append({
            **common, "role": "tool", "tool_name": "<result>",
            "tool_call_id": str(payload.get("call_id") or payload.get("id") or state.get("tool_seq", 0)),
            "input": None, "output": payload.get("output"),
        })
        state["tool_seq"] = state.get("tool_seq", 0) + 1
        return out

    if item_type == "web_search_call":
        out.append({
            **common, "role": "tool", "tool_name": "web_search",
            "tool_call_id": str(payload.get("id") or state.get("tool_seq", 0)),
            "input": payload.get("action"), "output": None,
        })
        state["tool_seq"] = state.get("tool_seq", 0) + 1
        return out

    out.append({
        **common, "role": "system",
        "text": f"[unsupported codex item: {item_type}]",
        "metadata": {"dropped": True, "original_type": item_type},
    })
    return out
